import {modules,moduleGroups,statuses,fieldGroups,listSchemas} from './modules.mjs';
import {loadWorkspace,saveWorkspace,validateWorkspace,migrateLegacySnapshot,newProject,cloneProject,createRelease,restoreRelease,reviewProject} from './store.mjs';
import {buildDocument,esc} from './document.mjs';

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let workspace=loadWorkspace(),active=null,activeView='project',saveTimer,toastTimer;
const viewMeta={project:['المشروع والإصدار','بيانات الغلاف وضبط المستند والتعيين'],organization:['الأطراف والفريق','الشركات والأدوار والأشخاص المسؤولون'],information:['المعلومات والمنصات','المراجع، الاستخدامات، CDE والبرامج'],technical:['الموديلات والمعايير','سجل الموديلات والتسمية والإحداثيات'],coordination:['التنسيق والتسليم','المراحل والتسليمات والكلاشات والاجتماعات'],modules:['محتوى الـBEP','حالة كل وحدة والنصوص الخاصة بالمشروع'],review:['المراجعة والإصدارات','النواقص، التعارضات والنسخ الثابتة'],appearance:['الهوية والطباعة','شكل المستند والعناصر الظاهرة'],preview:['معاينة المستند','النسخة الإنجليزية القابلة للطباعة']};
const viewLists={organization:['parties','team'],information:['references','uses','software'],technical:['models'],coordination:['milestones','deliverables','clashes','meetings']};
function notify(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function current(){return workspace.projects.find(p=>p.id===workspace.activeProjectId)||null;}
function persist(){if(!active)return;active.updatedAt=new Date().toISOString();try{saveWorkspace(workspace);$('#save-status').textContent='محفوظ محليًا';}catch{$('#save-status').textContent='تعذر الحفظ';notify('مساحة التخزين المحلية غير كافية. نزّل نسخة احتياطية قبل المتابعة.');}}
function changed(){if(!active)return;$('#save-status').textContent='جارٍ الحفظ…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{persist();renderReadiness();},250);}
function statusText(p){const r=reviewProject(p);return r.ready?'جاهز لمراجعة الإصدار':`${r.critical} نقص أساسي`;}

function renderDashboard(){
  active=null;workspace.activeProjectId=null;saveWorkspace(workspace);$('#editor').hidden=true;$('#dashboard').hidden=false;$('#current-project-name').textContent='المشروعات';$$('.editor-only').forEach(x=>x.hidden=true);
  const live=workspace.projects.filter(p=>!p.archived),archived=workspace.projects.filter(p=>p.archived),ready=live.filter(p=>reviewProject(p).ready).length;
  $('#portfolio-summary').innerHTML=`<article><span>المشروعات النشطة</span><strong>${live.length}</strong></article><article><span>جاهزة للمراجعة</span><strong>${ready}</strong></article><article><span>إصدارات مثبتة</span><strong>${workspace.projects.reduce((n,p)=>n+p.releases.length,0)}</strong></article><article><span>مؤرشفة</span><strong>${archived.length}</strong></article>`;
  const q=$('#project-search').value.trim().toLowerCase(),matches=workspace.projects.filter(p=>`${p.fields.projectName} ${p.fields.projectCode}`.toLowerCase().includes(q));
  $('#project-list').innerHTML=matches.length?matches.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(p=>{const r=reviewProject(p);return `<article class="project-card ${p.archived?'archived':''}" data-id="${p.id}"><div class="project-card-top"><span class="project-code">${esc(p.fields.projectCode||'NO CODE')}</span><span class="score ${r.ready?'ready':''}">${r.score}%</span></div><h3>${esc(p.fields.projectName||'Untitled project')}</h3><p>${esc(p.fields.client||'Client not assigned')}</p><div class="project-meta"><span>${statusText(p)}</span><span>${p.releases.length} إصدار</span></div><div class="card-actions"><button data-action="open" class="button primary">فتح</button><button data-action="duplicate" class="icon-button" title="نسخ المشروع">⧉</button><button data-action="archive" class="icon-button" title="${p.archived?'استعادة':'أرشفة'}">${p.archived?'↥':'⌄'}</button><button data-action="delete" class="icon-button danger-text" title="حذف">×</button></div></article>`}).join(''):`<div class="empty-state"><strong>لا توجد مشروعات</strong><p>ابدأ مشروع BEP جديد، وستُحفظ بياناته تلقائيًا على هذا الجهاز.</p></div>`;
}
function openProject(id){workspace.activeProjectId=id;active=current();if(!active)return;saveWorkspace(workspace);$('#dashboard').hidden=true;$('#editor').hidden=false;$$('.editor-only').forEach(x=>x.hidden=false);$('#current-project-name').textContent=active.fields.projectName||'مشروع بلا اسم';showView('project');}
function renderReadiness(){if(!active)return;const r=reviewProject(active);$('#readiness-value').textContent=`${r.score}%`;$('#readiness-bar').style.width=`${r.score}%`;$('#readiness-label').textContent=r.ready?'لا توجد نواقص تمنع الإصدار':`${r.critical} أساسية · ${r.warnings} تنبيهات`;$('#current-project-name').textContent=active.fields.projectName||'مشروع بلا اسم';}
function fieldInput([key,label,type,required,options]){const value=active.fields[key]||'',req=required?'<span class="required">مطلوب</span>':'';if(type==='textarea')return `<label class="field wide"><span>${label}${req}</span><textarea data-field="${key}" rows="4">${esc(value)}</textarea></label>`;if(type==='select')return `<label class="field"><span>${label}${req}</span><select data-field="${key}">${options.map(o=>`<option ${value===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;return `<label class="field"><span>${label}${req}</span><input data-field="${key}" type="${type}" value="${esc(value)}"></label>`;}
function fieldsCard(title,group){return `<section class="form-card"><h2>${title}</h2><div class="field-grid">${fieldGroups[group].map(fieldInput).join('')}</div></section>`;}
function listEditor(key){const schema=listSchemas[key],rows=active.lists[key];return `<section class="form-card table-card"><div class="card-heading"><div><h2>${schema.label}</h2><p>${rows.length} سجل</p></div><button class="button secondary" data-add-row="${key}">+ إضافة صف</button></div><div class="table-scroll"><table class="editor-table"><thead><tr>${schema.columns.map(c=>`<th>${c[1]}</th>`).join('')}<th></th></tr></thead><tbody>${rows.length?rows.map((row,i)=>`<tr>${schema.columns.map(([col])=>`<td><input data-list="${key}" data-row="${i}" data-col="${col}" value="${esc(row[col]||'')}"></td>`).join('')}<td><button class="row-delete" data-delete-row="${key}" data-row="${i}" aria-label="حذف الصف">×</button></td></tr>`).join(''):`<tr><td colspan="${schema.columns.length+1}" class="empty-cell">لا توجد سجلات — أضف أول صف.</td></tr>`}</tbody></table></div></section>`;}
function renderFormView(){
  if(!active)return;const root=$('#form-view');
  if(activeView==='project')root.innerHTML=fieldsCard('بيانات المشروع','project')+fieldsCard('التعيين والنطاق','appointment');
  else if(activeView==='organization')root.innerHTML=viewLists.organization.map(listEditor).join('');
  else if(activeView==='information')root.innerHTML=fieldsCard('بيئة البيانات والإجراءات','information')+viewLists.information.map(listEditor).join('');
  else if(activeView==='technical')root.innerHTML=fieldsCard('المعايير الفنية','technical')+listEditor('models');
  else if(activeView==='coordination')root.innerHTML=fieldsCard('إعدادات التنسيق والإغلاق','coordination')+viewLists.coordination.map(listEditor).join('');
  else if(activeView==='modules')root.innerHTML=moduleGroups.map(g=>`<section class="form-card"><h2>${g.label}</h2><div class="module-grid">${modules.filter(m=>m.group===g.id).map(m=>`<article class="module-card"><div><strong>${m.ar}</strong><span>${m.title}</span><p>${m.desc}</p></div><select data-module="${m.id}">${statuses.map(s=>`<option value="${s.value}" ${active.moduleStates[m.id]===s.value?'selected':''}>${s.label}</option>`).join('')}</select><label>نص خاص بالمشروع<textarea data-note="${m.id}" rows="2" placeholder="يضاف إلى نهاية هذا القسم">${esc(active.notes[m.id]||'')}</textarea></label></article>`).join('')}</div></section>`).join('');
  else if(activeView==='review')renderReview(root);
  else if(activeView==='appearance')root.innerHTML=`<section class="form-card"><h2>هوية المستند</h2><div class="field-grid"><label class="field"><span>اللون الرئيسي</span><input type="color" data-style="accent" value="${active.style.accent}"></label><label class="field"><span>نوع خط المستند</span><select data-style="font"><option value="sans" ${active.style.font==='sans'?'selected':''}>Arial / Sans serif</option><option value="serif" ${active.style.font==='serif'?'selected':''}>Georgia / Serif</option></select></label><label class="check"><input type="checkbox" data-style="cover" ${active.style.cover?'checked':''}>إظهار الغلاف</label><label class="check"><input type="checkbox" data-style="toc" ${active.style.toc?'checked':''}>إظهار الفهرس</label><label class="check"><input type="checkbox" data-style="showNotApplicable" ${active.style.showNotApplicable?'checked':''}>إظهار قائمة الأقسام غير المنطبقة</label></div></section><section class="form-card"><h2>الطباعة</h2><p>استخدم A4، فعّل Background graphics، وألغِ Headers and footers الخاصة بالمتصفح. الجداول الواسعة قابلة للتمرير أثناء التحرير وتُضغط داخل عرض الصفحة عند الطباعة.</p><button class="button primary" data-open-preview>فتح المعاينة</button></section>`;
  bindFormEvents();
}
function renderReview(root){const r=reviewProject(active);root.innerHTML=`<section class="review-hero ${r.ready?'ready':''}"><div><span>${r.ready?'READY FOR ISSUE REVIEW':'WORKING DRAFT'}</span><h2>${r.score}% جاهزية</h2><p>${r.ready?'اكتملت المتطلبات الأساسية. راجع المحتوى ثم ثبّت الإصدار.':'أكمل البنود الأساسية قبل تثبيت إصدار رسمي.'}</p></div><button class="button primary" id="create-release" ${r.ready?'':'disabled'}>تثبيت الإصدار ${esc(active.fields.revision||'')}</button></section><section class="form-card"><div class="card-heading"><h2>نتائج المراجعة</h2><span>${r.critical} أساسية · ${r.warnings} تنبيهات</span></div><div class="issue-list">${r.issues.length?r.issues.map(i=>`<article class="issue ${i.severity}"><b>${i.severity==='critical'?'يلزم الحل':'تنبيه'}</b><span>${esc(i.message)}</span></article>`).join(''):'<div class="success-state">لا توجد نواقص مسجلة.</div>'}</div></section><section class="form-card"><div class="card-heading"><h2>الإصدارات المثبتة</h2><span>لا تتغير بتعديل المسودة الحالية</span></div><div class="release-list">${active.releases.length?active.releases.slice().reverse().map(r=>`<article><div><strong>${esc(r.revision)}</strong><span>الإصدار ${r.number} · ${esc(r.issueDate)} · جاهزية ${r.readiness}%</span></div><button class="button ghost" data-restore-release="${r.id}">استعادة كمسودة</button></article>`).join(''):'<p class="empty-cell">لا توجد إصدارات مثبتة حتى الآن.</p>'}</div></section>`;}
function bindFormEvents(){
  $$('[data-field]').forEach(el=>el.addEventListener('input',()=>{active.fields[el.dataset.field]=el.value;changed();}));
  $$('[data-list]').forEach(el=>el.addEventListener('input',()=>{active.lists[el.dataset.list][+el.dataset.row][el.dataset.col]=el.value;changed();}));
  $$('[data-add-row]').forEach(btn=>btn.addEventListener('click',()=>{const key=btn.dataset.addRow;active.lists[key].push(Object.fromEntries(listSchemas[key].columns.map(([c])=>[c,''])));changed();renderFormView();}));
  $$('[data-delete-row]').forEach(btn=>btn.addEventListener('click',()=>{active.lists[btn.dataset.deleteRow].splice(+btn.dataset.row,1);changed();renderFormView();}));
  $$('[data-module]').forEach(el=>el.addEventListener('change',()=>{active.moduleStates[el.dataset.module]=el.value;const mod=modules.find(m=>m.id===el.dataset.module);if(el.value!=='not_applicable'&&mod?.depends)for(const dep of mod.depends)if(active.moduleStates[dep]==='not_applicable')active.moduleStates[dep]='required';changed();renderFormView();notify('تم تحديث القسم والعناصر التابعة له.');}));
  $$('[data-note]').forEach(el=>el.addEventListener('input',()=>{active.notes[el.dataset.note]=el.value;changed();}));
  $$('[data-style]').forEach(el=>el.addEventListener('input',()=>{active.style[el.dataset.style]=el.type==='checkbox'?el.checked:el.value;changed();}));
  $$('[data-open-preview]').forEach(el=>el.addEventListener('click',()=>showView('preview')));
  $('#create-release')?.addEventListener('click',()=>{const n=createRelease(active);persist();renderFormView();notify(`تم تثبيت الإصدار رقم ${n}.`);});
  $$('[data-restore-release]').forEach(btn=>btn.addEventListener('click',async()=>{if(await confirmAction('استعادة الإصدار','سيتم استبدال المسودة الحالية ببيانات هذا الإصدار.')){restoreRelease(active,btn.dataset.restoreRelease);persist();renderFormView();renderReadiness();notify('تمت استعادة الإصدار كمسودة قابلة للتعديل.');}}));
}
function showView(view){activeView=view;$$('#editor-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const [title,desc]=viewMeta[view];$('#view-heading').innerHTML=`<span class="eyebrow">BEP WORKSPACE</span><h1>${title}</h1><p>${desc}</p>`;const preview=view==='preview';$('.workarea').hidden=preview;$('#document-pane').classList.toggle('show',preview);if(preview){const r=reviewProject(active);document.documentElement.style.setProperty('--accent',active.style.accent);document.documentElement.style.setProperty('--doc-font',active.style.font==='serif'?'Georgia,serif':'Arial,sans-serif');$('#document').innerHTML=buildDocument(active,r);}else renderFormView();renderReadiness();}
function confirmAction(title,message){return new Promise(resolve=>{const d=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;d.addEventListener('close',()=>resolve(d.returnValue==='confirm'),{once:true});d.showModal();});}

$('#new-project').addEventListener('click',()=>{$('#new-project-form').reset();$('#project-dialog').showModal();});
$('#new-project-form').addEventListener('submit',event=>{event.preventDefault();const submitter=event.submitter;if(submitter?.value!=='create'){$('#project-dialog').close('cancel');return;}const data=new FormData(event.currentTarget),p=newProject({projectName:String(data.get('name')).trim(),projectCode:String(data.get('code')).trim(),contractor:String(data.get('contractor')).trim()});workspace.projects.push(p);saveWorkspace(workspace);$('#project-dialog').close('create');openProject(p.id);});
$('#project-list').addEventListener('click',async event=>{const btn=event.target.closest('button[data-action]');if(!btn)return;const card=btn.closest('[data-id]'),p=workspace.projects.find(x=>x.id===card.dataset.id);if(btn.dataset.action==='open')openProject(p.id);if(btn.dataset.action==='duplicate'){workspace.projects.push(cloneProject(p));saveWorkspace(workspace);renderDashboard();notify('تم إنشاء نسخة مستقلة من المشروع.');}if(btn.dataset.action==='archive'){p.archived=!p.archived;p.updatedAt=new Date().toISOString();saveWorkspace(workspace);renderDashboard();}if(btn.dataset.action==='delete'&&await confirmAction('حذف المشروع',`سيتم حذف ${p.fields.projectName} وإصداراته من هذا الجهاز نهائيًا.`)){workspace.projects=workspace.projects.filter(x=>x.id!==p.id);saveWorkspace(workspace);renderDashboard();}});
$('#project-search').addEventListener('input',renderDashboard);$('#back-dashboard').addEventListener('click',renderDashboard);$('#go-home').addEventListener('click',renderDashboard);
$$('#editor-nav button').forEach(btn=>btn.addEventListener('click',()=>showView(btn.dataset.view)));$('#close-preview').addEventListener('click',()=>showView('review'));
$('#print').addEventListener('click',()=>{if(!active)return;const r=reviewProject(active);showView('preview');if(!r.ready&&!confirm('المستند يحتوي نواقص أساسية وسيظهر كمسودة غير مكتملة. هل تريد متابعة الطباعة؟'))return;setTimeout(()=>window.print(),50);});
$('#backup-all').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({...workspace,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`bep-studio-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('تم تجهيز النسخة الاحتياطية.');});
$('#restore-all').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>10_000_000)throw new Error('الملف أكبر من 10MB.');const raw=JSON.parse(await file.text()),loaded=raw.schemaVersion===2?validateWorkspace(raw):validateWorkspace(migrateLegacySnapshot(raw));if(await confirmAction('استعادة النسخة الاحتياطية','سيتم استبدال جميع المشروعات المحفوظة على هذا الجهاز.')){workspace=loaded;saveWorkspace(workspace);renderDashboard();notify(raw.version===1?'تم تحويل نسخة النموذج القديم واستعادتها.':'تمت استعادة المشروعات والإصدارات.');}}catch(error){notify(error instanceof SyntaxError?'ملف JSON غير صالح.':error.message);}finally{event.target.value='';}});
window.addEventListener('storage',()=>{workspace=loadWorkspace();if(!active)renderDashboard();});
renderDashboard();
